protected void setValues()
{
    prodTable prodTable = common;
    InventTable itemTable = InventTable::find(prodTable.ItemId);
    super();
    inventDim = prodTable.inventDim();
    displayLine1 = new DictType(extendedTypeName2Id(extendedTypeStr(ProdID))).label() + ': ' + prodTable.prodID;
    displayLine2 = "@SYS319915" + ': ' + itemTable.productName(new xInfo().language());
    displayLine3 = "@SYS330532" + ': ' + prodTable.ItemId;
    //displayLine4 = this.getSQLStatement();
    //docuRef = MobHelper::findDefaultImageDocuRef(itemTable);
    imageId = MobHelper::imageIDFromDocuref(MobHelper::FindItemDocuref(prodTable.itemId,prodTable.InventDimId));

    fieldsToAdd.insert(MobConstants::Quantity(), MobHelper::formatItemQty(prodTable.RemainInventPhysical, InventTable::find(prodTable.ItemId).inventUnitId()));
    fieldsToAdd.insert(strLwr(extendedTypeStr(ProdId)),   ProdTable.ProdId);
    fieldsToAdd.insert(MobConstants::ScrapQuantity(), '0');
    fieldsToAdd.insert(tableStr(UnitOfMeasure), itemTable.inventUnitId());
    fieldsToAdd.insert(MobConstants::Barcode(), InventItemBarcode::findByProductDimensions(itemTable.ItemId, prodTable.inventDim(), false, true).itemBarCode);

    displayLine5 = "@SYS106860" + ': ' + fieldsToAdd.lookup(MobConstants::Quantity()) + ' ' + itemTable.inventUnitId();
}

